-- migrations/0004_fts_update_trigger_columns.sql
-- Re-index FTS only when a searchable column changes. Without the column list, every UPDATE
-- (coordinates, expiry date, suspension fields) rewrote the FTS entry, multiplying D1 row writes.

DROP TRIGGER IF EXISTS restaurants_fts_au;

